/* Weapon-specific editor. All changes stay in a draft until saved. */
(function(root){
  'use strict';
  function open({db,source={},copy=false,onSave}){
    const G=root.GogArtian,DATA=root.WILDS_GOG_DATA,dialog=document.querySelector('#editor'),host=document.querySelector('#editor-content');
    const $=s=>host.querySelector(s),$$=s=>[...host.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const option=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
    const nameMatch=G.detectName(source.name,db),detected=source.gogConfig?{}:nameMatch,kind=detected.kind||source.kind||'long-sword';
    const category=detected.category||source.category||(source.originId?'일반 무기':'아티어');
    let config=source.gogConfig?structuredClone(source.gogConfig):G.emptyConfig(kind),tags={...source.tags},manualSkills={...source.skills};
    let lastNameElement=nameMatch.element;
    if(detected.element)config.element=detected.element;
    if(!source.gogConfig&&source.originId){const profile=DATA.profiles[kind];for(const [focus,base]of Object.entries(profile?.intensifications||{}))if(base.originId===source.originId)config.intensification=focus;}
    const isGog=()=>$('#edit-category').value==='거극 아티어';
    const skillSelect=(id='',bonusKind=null,onlyGog=false)=>option('','선택 안 함',id)+db.skills.filter(s=>bonusKind?s.kind===bonusKind&&(!onlyGog||DATA.allowedTags[bonusKind].includes(s.id)):!['set','group'].includes(s.kind)).sort((a,b)=>a.name.localeCompare(b.name,'ko')).map(s=>option(s.id,s.name,id)).join('');
    const skillRow=(id='',n=1)=>`<div class="edit-skill"><select class="weapon-skill" aria-label="무기 기본 스킬">${skillSelect(id)}</select><input class="weapon-skill-level" aria-label="기본 스킬 레벨" type="number" min="1" max="${db.skills.find(s=>s.id===id)?.maxLevel||5}" value="${n}"><button type="button" class="delete-weapon-skill" aria-label="스킬 삭제">×</button></div>`;
    host.innerHTML=`<button type="button" id="close-weapon-editor" class="icon-button close" aria-label="닫기">×</button><h2>무기 ${source.id&&!copy?'수정':'등록'}</h2><p class="hint" id="weapon-intro">이름에서 무기 종류와 거극 아티어 속성을 자동으로 선택합니다.</p><form id="weapon-form"><div class="form-grid"><label class="field full">무기 이름<span class="weapon-name-field"><span id="weapon-draft-icon">${root.WildsIcons?.weapon(kind)||''}</span><input id="edit-name" maxlength="80" required value="${esc(source.name)}" placeholder="예: 용속 거극아티어 건랜스 / 전조의 프로페네시스 [빙]" autocomplete="off"></span><span id="weapon-name-hint" class="hint" role="status"></span></label><label class="field">무기 분류<select id="edit-category">${['일반 무기','아티어','거극 아티어'].map(n=>option(n,n,category)).join('')}</select></label><label class="field">무기 종류<select id="edit-kind">${Object.entries(G.WEAPONS).map(([id,n])=>option(id,n,kind)).join('')}</select></label></div><section id="gog-section"></section><section id="manual-weapon-section"><div class="form-grid"><label class="field">표시 공격력<input id="edit-attack" type="number" min="0" max="9999" value="${source.attack||0}"></label><label class="field">회심률 (%)<input id="edit-affinity" type="number" min="-100" max="100" value="${source.affinity||0}"></label><label class="field">방어력 보너스<input id="edit-defense" type="number" min="0" max="999" value="${source.defense||0}"></label></div><div class="form-section"><h3>장식주 슬롯</h3><div class="row">${Array.from({length:3},(_,i)=>`<label class="field">${i+1}번<select class="weapon-manual-slot" aria-label="${i+1}번 무기 슬롯">${[0,1,2,3].map(n=>option(n,n?'무기용 Lv '+n:'없음',source.slots?.[i]?.level||0)).join('')}</select></label>`).join('')}</div></div><div class="form-section"><div class="row between"><h3>기본 스킬</h3><button type="button" id="add-weapon-skill">＋ 스킬</button></div><div id="manual-weapon-skills">${Object.keys(manualSkills).length?Object.entries(manualSkills).map(([id,n])=>skillRow(id,n)).join(''):skillRow()}</div></div></section><div class="form-section"><h3>시리즈 · 그룹 스킬</h3><div class="form-grid"><label class="field">시리즈 스킬<select id="weapon-series">${skillSelect(Object.keys(tags).find(id=>db.skills.find(s=>s.id===id)?.kind==='set'),'set')}</select></label><label class="field">그룹 스킬<select id="weapon-group">${skillSelect(Object.keys(tags).find(id=>db.skills.find(s=>s.id===id)?.kind==='group'),'group')}</select></label></div><p class="hint">각 1부위로 계산합니다. 선택하지 않은 스킬은 검색에 반영되지 않습니다.</p></div><label class="field">메모<input id="edit-notes" maxlength="200" value="${esc(source.notes)}" placeholder="파밍 메모, 사용할 세팅 등"></label><p id="weapon-error" class="warning-text hint" role="alert"></p><div class="form-actions"><button type="button" id="cancel-weapon-editor">취소</button><button type="submit" class="primary">무기 저장</button></div></form>`;
    const close=()=>{dialog.classList.remove('weapon-dialog');dialog.close();};
    $('#close-weapon-editor').onclick=close;$('#cancel-weapon-editor').onclick=close;
    function bindSkills(){for(const b of $$('.delete-weapon-skill'))b.onclick=()=>b.parentElement.remove();for(const s of $$('.weapon-skill'))s.onchange=()=>{const n=s.parentElement.querySelector('input');n.max=db.skills.find(x=>x.id===s.value)?.maxLevel||5;n.value=Math.min(+n.value,+n.max);};}
    $('#add-weapon-skill').onclick=()=>{if($$('.weapon-skill').length<10){$('#manual-weapon-skills').insertAdjacentHTML('beforeend',skillRow());bindSkills();}};bindSkills();
    function updateForKind(){const k=$('#edit-kind').value;const allowed=G.bonusTypes(k,config.element);let cleared=false;config.restoration=config.restoration.map(b=>{if(b.type&&!allowed.includes(b.type)){cleared=true;return {type:'',tier:''};}return b;});if(cleared)$('#weapon-name-hint').textContent='새 무기에서 사용할 수 없는 보너스는 비웠습니다.';renderMode();}
    function nameHint(match){const labels=[match.category,match.kind?G.WEAPONS[match.kind]:null,isGog()&&match.element===config.element?G.ELEMENTS[match.element]:null].filter(Boolean);return [labels.length?labels.join(' · ')+' 자동 선택':'',isGog()&&match.elementAmbiguous?'속성이 여러 개 있어 현재 선택을 유지합니다. 속성을 하나만 적거나 직접 선택하세요.':''].filter(Boolean).join(' / ');}
    function recognizeName(e){if(e.isComposing)return;const match=G.detectName($('#edit-name').value,db);if(match.kind)$('#edit-kind').value=match.kind;if(match.category)$('#edit-category').value=match.category;if(match.element&&match.element!==lastNameElement)config.element=match.element;lastNameElement=match.element;$('#weapon-name-hint').textContent=nameHint(match);updateForKind();}
    $('#edit-name').addEventListener('input',recognizeName);$('#edit-name').addEventListener('compositionend',recognizeName);
    $('#edit-kind').onchange=updateForKind;$('#edit-category').onchange=()=>renderMode();
    function renderMode(){const gog=isGog();$('#weapon-draft-icon').innerHTML=root.WildsIcons?.weapon($('#edit-kind').value)||'';$('#gog-section').hidden=!gog;$('#manual-weapon-section').hidden=gog;for(const el of $$('#manual-weapon-section input, #manual-weapon-section select'))el.disabled=gog;$('#weapon-intro').textContent=gog?'격화와 복원 보너스 5개를 고르면 수치가 자동 계산됩니다.':'이름에서 무기 종류와 거극 아티어 속성을 자동으로 선택합니다.';for(const [selector,kind]of [['#weapon-series','set'],['#weapon-group','group']]){const select=$(selector),value=select.value;select.innerHTML=skillSelect(value,kind,gog);}if(gog)renderGog();else $('#gog-section').innerHTML='';}
    function renderGog(){
      const k=$('#edit-kind').value,profile=DATA.profiles[k];
      $('#gog-section').innerHTML=`<div class="gog-header"><div><span class="eyebrow">GOG ARTIAN</span><h3>${esc(profile.name)}</h3></div><span class="badge gold">무기 슬롯 <strong>3 · 3 · 3</strong> 고정</span></div><div class="form-grid"><label class="field">격화 종류${k==='gunlance'?' · 포격형':''}<select id="gog-focus">${Object.entries(G.FOCUS).map(([id,n])=>option(id,n+(k==='gunlance'?' · '+G.SHELLS[profile.intensifications[id].shell]:''),config.intensification)).join('')}</select></label><label class="field">${G.isBowgun(k)?'제작 파츠 속성 · 탄 구성':k==='bow'?'속성 · 병 구성':'속성 / 상태이상'}<span class="icon-select">${root.WildsIcons?.element(config.element)||''}<select id="gog-element" required>${option('','선택하세요',config.element)}${Object.entries(G.ELEMENTS).map(([id,n])=>option(id,n,config.element)).join('')}</select></span></label></div><details class="gog-production"><summary>생산 보너스: 공격력 ${config.productionAttack}개${config.productionAttack<3?' · 회심 '+(3-config.productionAttack)+'개':''} <span class="hint">변경</span></summary><div class="form-grid"><label class="field">생산 보너스 3개 조합<select id="gog-production">${[3,2,1,0].map(n=>option(n,'공격력 '+n+'개 + 회심 '+(3-n)+'개',config.productionAttack)).join('')}</select></label><label class="field">동일 속성 파츠<select id="gog-matching" ${config.element==='none'?'disabled':''}>${option(3,'3개 · 속성 일치 보너스 적용',config.matchingParts)}${option(2,'2개 · 속성 일치 보너스 없음',config.matchingParts)}</select></label></div><p class="hint">거극 아티어로 강화하기 전 사용한 생산 파츠입니다. 복원 보너스와 별개로 계산합니다.</p></details><div class="form-section"><div class="row between"><h3>복원 보너스</h3><span class="badge" id="gog-count">${config.restoration.filter(b=>b.type).length} / 5</span></div><div class="gog-bonus-head"><span></span><span>보너스 종류</span><span>레벨</span><span>증가량</span></div>${config.restoration.map((b,i)=>`<div class="gog-bonus-row"><span class="bonus-number">${i+1}</span><select class="gog-bonus-type" data-index="${i}" required aria-label="복원 보너스 ${i+1} 종류">${option('','선택하세요',b.type)}${G.bonusTypes(k,config.element).map(type=>option(type,G.BONUS_NAMES[type],b.type)).join('')}</select><select class="gog-bonus-tier" data-index="${i}" aria-label="복원 보너스 ${i+1} 레벨" ${b.type?'':'disabled'}>${b.type?G.bonusTiers(b.type).map(t=>option(t,t,b.tier)).join(''):option('','—','')}</select><output class="gog-bonus-value" data-index="${i}">—</output></div>`).join('')}<p class="hint" style="margin-top:.7rem">재추첨 보너스는 같은 종류·레벨당 최대 2개입니다. 공격·회심·속성의 I는 거극 복원강화 전 계승한 옵션입니다.</p></div><div id="gog-preview" class="gog-preview" aria-live="polite"></div><p id="gog-error" class="warning-text hint" role="alert"></p><p class="hint">무기용 3레벨 슬롯 3개와 방어력 보너스 0은 고정입니다. 일반 고유 스킬은 없습니다.</p>`;
      $('#gog-focus').onchange=e=>{config.intensification=e.target.value;updatePreview();};
      $('#gog-element').onchange=e=>{config.element=e.target.value;updateForKind();};
      $('#gog-production').onchange=e=>{config.productionAttack=+e.target.value;renderGog();};
      $('#gog-matching').onchange=e=>{config.matchingParts=+e.target.value;updatePreview();};
      for(const el of $$('.gog-bonus-type'))el.onchange=()=>{const b=config.restoration[+el.dataset.index];b.type=el.value;b.tier=b.type?(G.bonusTiers(b.type).includes(b.tier)?b.tier:G.bonusTiers(b.type).find(t=>t!=='I')||'I'):'';renderGog();};
      for(const el of $$('.gog-bonus-tier'))el.onchange=()=>{config.restoration[+el.dataset.index].tier=el.value;updatePreview();};
      updatePreview();
    }
    function updatePreview(){
      try{
        const k=$('#edit-kind').value,result=G.calculate(k,config,{allowIncomplete:true}),b=result.breakdown;$('#gog-error').textContent='';
        $('#gog-preview').innerHTML=`<div class="row between"><strong>자동 계산 ${result.complete?'':'· 선택한 옵션 기준'}</strong>${result.shell?`<span class="badge gold">${G.SHELLS[result.shell]} · ${result.shellPower}</span>`:''}</div><div class="gog-stats"><div><small>표시 공격력</small><strong id="gog-attack">${result.attack}</strong><small>기초 ${result.rawAttack}</small></div><div><small>회심률</small><strong id="gog-affinity">${result.affinity}%</strong></div><div><small class="element-stat">${G.isBowgun(k)?'':root.WildsIcons?.element(config.element)||''}${G.isBowgun(k)?'장전 보너스':G.ELEMENTS[config.element]||'속성'}</small><strong id="gog-element-value">${G.isBowgun(k)?'+'+result.ammoBonus:result.elementValue??'—'}</strong></div>${result.sharpness?`<div><small>흰 예리도</small><strong>${result.sharpness.white}</strong></div>`:''}</div><details><summary>계산 내역</summary><p>기초 공격력 ${b.baseRaw} + 생산 ${b.productionRaw} + 복원 ${b.restorationRaw} = ${result.rawAttack}<br>회심 ${b.baseAffinity}% + 생산 ${b.productionAffinity}% + 복원 ${b.restorationAffinity}% = ${result.affinity}%${result.elementValue?`<br>속성 ${b.baseElement} + 파츠 일치 ${b.infusion} + 복원 ${b.restorationElement} = ${result.elementValue}`:''}</p></details>${G.isBowgun(k)||k==='bow'&&['poison','paralysis','sleep'].includes(config.element)?'<p class="hint">선택한 속성은 탄·병 구성을 뜻하며 숫자 속성 공격력으로 더하지 않습니다.</p>':''}`;
        config.restoration.forEach((entry,index)=>{const out=$(`.gog-bonus-value[data-index="${index}"]`);const found=entry.type?b.details.filter(d=>d.type===entry.type&&d.tier===entry.tier)[0]:null;out.textContent=found?'+'+found.value+(entry.type==='affinity'?'%':''):'—';});
        $('#gog-count').textContent=result.selected+' / 5';
      }catch(e){$('#gog-error').textContent=e.message;$('#gog-preview').innerHTML='<p class="hint">보너스 선택을 확인하면 수치가 표시됩니다.</p>';for(const el of $$('.gog-bonus-value'))el.textContent='—';}
    }
    $('#weapon-form').onsubmit=e=>{
      e.preventDefault();try{
        const name=$('#edit-name').value.trim();if(!name)throw new Error('무기 이름을 입력하세요.');
        const selectedTags={};for(const id of [$('#weapon-series').value,$('#weapon-group').value])if(id)selectedTags[id]=1;
        let result={...source,name,kind:$('#edit-kind').value,category:$('#edit-category').value,notes:$('#edit-notes').value.trim(),tags:selectedTags};
        if(isGog()){G.validateTags(selectedTags);const calculated=G.calculate(result.kind,config);result={...result,...calculated,name,gogConfig:structuredClone(config),baseWeaponName:calculated.name};delete result.complete;delete result.selected;delete result.breakdown;}
        else{const skills={};for(const el of $$('.weapon-skill')){if(!el.value)continue;const level=+el.parentElement.querySelector('input').value;const skill=db.skills.find(s=>s.id===el.value);if(skills[el.value]||!Number.isInteger(level)||level<1||level>skill.maxLevel)throw new Error('스킬 중복 또는 레벨을 확인하세요.');skills[el.value]=level;}result={...result,skills,attack:+$('#edit-attack').value,affinity:+$('#edit-affinity').value,defense:+$('#edit-defense').value,slots:$$('.weapon-manual-slot').filter(s=>+s.value).map(s=>({kind:'weapon',level:+s.value}))};delete result.gogConfig;}
        onSave(result);close();
      }catch(error){$('#weapon-error').textContent=error.message;}
    };
    renderMode();$('#weapon-name-hint').textContent=nameHint(detected);
    dialog.addEventListener('close',()=>dialog.classList.remove('weapon-dialog'),{once:true});dialog.classList.add('weapon-dialog');dialog.showModal();$('#edit-name').focus();
  }
  root.WildsWeaponEditor={open};
})(globalThis);
